const input = $input.first().json || {};

// n8n Cloud compatible config: $vars is permitted (OS env vars are blocked on n8n Cloud)
const varsObj = (typeof $vars !== 'undefined' && $vars) ? $vars : {};
const expectedSecret = varsObj.AUTOMATION_SECRET ? String(varsObj.AUTOMATION_SECRET) : '';

// Fail-closed webhook signature gate BEFORE merging with Schedule branch
const headers = input.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const signature = headers['x-agencydesk-signature'] || headers['X-AgencyDesk-Signature'] || (authHeader ? String(authHeader).replace(/^Bearer\s+/i, '') : '');
if (!expectedSecret || signature !== expectedSecret) {
  throw new Error('Unauthorized lifecycle webhook request.');
}

const payload = (input.body && typeof input.body === 'object') ? input.body : input;
return [{
  json: {
    ...payload,
    triggered_by: 'webhook'
  }
}];

const item = $input.first().json || {};

// n8n Cloud compatible config: $vars is permitted (OS env vars are blocked on n8n Cloud)
const varsObj = (typeof $vars !== 'undefined' && $vars) ? $vars : {};
const isSchedule = item.triggered_by === 'schedule';

const eventType = String(item.event_type || item.event || (isSchedule ? 'stale_lead_check' : 'lead_stage_changed')).toLowerCase().trim();
const rawStage = String(item.stage || item.status || '').toLowerCase().trim().replace(/\s+/g, '_');

let routeBranch = 'other_stage';
if (eventType === 'stale_lead_check' || isSchedule) {
  routeBranch = 'stale_lead_check';
} else if (eventType === 'proposal_accepted' || rawStage === 'won') {
  routeBranch = 'proposal_accepted';
} else if (eventType === 'proposal_published' || rawStage === 'proposal_sent') {
  routeBranch = 'proposal_published';
} else if (rawStage === 'contacted' || rawStage === 'qualified') {
  routeBranch = 'contacted_qualified';
}

const stageToSheetLabel = {
  new: 'New Inquiry',
  contacted: 'Contacted',
  qualified: 'Qualified',
  proposal_sent: 'Proposal Sent',
  won: 'WON',
  lost: 'Lost'
};
const effectiveStage = routeBranch === 'proposal_accepted' ? 'won' : (routeBranch === 'proposal_published' ? 'proposal_sent' : (rawStage || 'new'));
const sheetStatusLabel = stageToSheetLabel[effectiveStage] || 'Open';

const appUrl = String(varsObj.AGENCYDESK_APP_URL || 'https://agencydesk-theta.vercel.app').replace(/\/+$/, '');
const leadId = item.lead_id || null;
const crmUrl = item.crm_url || (leadId ? `${appUrl}/crm/leads?lead=${leadId}` : `${appUrl}/crm/leads`);
const contactName = String(item.contact_name || 'Prospect').trim();
const company = String(item.company || item.company_name || 'Client Team').trim();
const service = String(item.service || 'Agency Services').trim();
const email = String(item.email || '').toLowerCase().trim();
const budget = Number(item.budget) || (Number(item.budget_cents) / 100) || 0;
const proposalTitle = String(item.proposal_title || `${company} — ${service} Proposal`).trim();
const ownerWhatsApp = varsObj.OWNER_WHATSAPP_NUMBER || '+639913780170';
const ownerEmail = varsObj.OWNER_EMAIL || 'kinggucci195@gmail.com';
const staleDays = Number(varsObj.STALE_LEAD_DAYS || 3) || 3;

let draftSubject = '';
let draftBody = '';
if (routeBranch === 'contacted_qualified') {
  draftSubject = `Next steps for ${company} — ${service}`;
  draftBody = `Hi ${contactName},\n\nThanks for connecting regarding ${service} for ${company}. Based on our initial review, I'd love to confirm your target timeline and key deliverables so we can prepare a tailored scope.\n\nWould a quick 20-minute discovery call work this week?\n\nBest,\nJustin\nAgencyDesk`;
} else if (routeBranch === 'proposal_published') {
  draftSubject = `Following up on your proposal: ${proposalTitle}`;
  draftBody = `Hi ${contactName},\n\nChecking in on the ${proposalTitle} scope we shared for ${company}. Let me know if you'd like any adjustments to milestones, timeline, or payment terms before kicking off.\n\nBest,\nJustin\nAgencyDesk`;
} else if (routeBranch === 'proposal_accepted') {
  draftSubject = `Welcome to AgencyDesk — ${company} Kickoff Plan`;
  draftBody = `Hi ${contactName},\n\nThank you for approving ${proposalTitle}! We're excited to kick off ${service} with ${company}.\n\nYour client portal is live here: ${appUrl}/portal\n\nNext steps:\n1. Confirm kickoff call time\n2. Share brand assets and system access\n3. Review Milestone 1 schedule\n\nBest,\nJustin\nAgencyDesk`;
}

return [{
  json: {
    triggered_by: isSchedule ? 'schedule' : 'webhook',
    event_type: eventType,
    route_branch: routeBranch,
    stage: effectiveStage,
    sheet_status_label: sheetStatusLabel,
    lead_id: leadId,
    contact_name: contactName,
    email,
    whatsapp: item.whatsapp || item.phone || null,
    company,
    service,
    budget,
    proposal_id: item.proposal_id || null,
    proposal_title: proposalTitle,
    project_id: item.project_id || null,
    crm_url: crmUrl,
    owner_whatsapp: ownerWhatsApp,
    owner_email: ownerEmail,
    stale_days: staleDays,
    draft_subject: draftSubject,
    draft_body: draftBody,
    followup_due_72h: new Date(Date.now() + 72 * 60 * 60 * 1000).toISOString(),
    processed_at: new Date().toISOString()
  }
}];

