const ctx = $('Normalize Lifecycle Event').first().json;
const rows = $input.all().map(item => item.json || {});
const staleDays = Number(ctx.stale_days || 3);
const cutoffMs = Date.now() - staleDays * 24 * 60 * 60 * 1000;

const escapeHtml = (val) => String(val ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const sanitizeHttpUrl = (raw, fallback) => {
  const str = String(raw || '').trim();
  return /^https?:\/\//i.test(str) ? str : fallback;
};

const safeBaseCrmUrl = sanitizeHttpUrl(ctx.crm_url, 'https://agencydesk-theta.vercel.app/crm/leads');

const closedStatuses = ['won', 'lost', 'closed', 'archived'];
const staleLeads = rows.filter(row => {
  const email = String(row.Email || '').trim();
  if (!email) return false;
  const status = String(row.Status || 'new').toLowerCase().trim();
  if (closedStatuses.includes(status)) return false;
  const tsRaw = row.Timestamp || row['Updated At'] || '';
  const tsMs = Date.parse(String(tsRaw));
  if (Number.isNaN(tsMs)) return false;
  return tsMs <= cutoffMs;
}).map(row => {
  const tsMs = Date.parse(String(row.Timestamp || row['Updated At'] || ''));
  const ageDays = Math.max(staleDays, Math.floor((Date.now() - tsMs) / (24 * 60 * 60 * 1000)));
  return {
    contact_name: String(row['Contact Name'] || 'Unknown'),
    company: String(row.Company || 'Unassigned'),
    service: String(row.Service || 'Agency Services'),
    email: String(row.Email || ''),
    status: String(row.Status || 'Open'),
    budget: Number(row.Budget || 0),
    score: Number(row.Score || 0),
    age_days: ageDays,
    crm_link: sanitizeHttpUrl(row['Website CRM Link'], safeBaseCrmUrl)
  };
}).sort((a, b) => b.age_days - a.age_days || b.score - a.score);

const topList = staleLeads.slice(0, 8);
const whatsappLines = [
  `☀️ *AGENCYDESK MORNING STALE LEADS DIGEST*`,
  `━━━━━━━━━━━━━━━━━━━━━`,
  `Found *${staleLeads.length}* open lead(s) untouched for ${staleDays}+ days:`,
  ...topList.map((l, idx) => `${idx + 1}. *${l.contact_name}* (${l.company}) — ${l.status} · ${l.age_days}d old · $${l.budget.toLocaleString()}\n   ${l.crm_link}`),
  `━━━━━━━━━━━━━━━━━━━━━`,
  `📊 Open Leads Sheet checked for ${ctx.owner_email}`
].join('\n');

const htmlRows = topList.map(l =>
  `<li><strong>${escapeHtml(l.contact_name)}</strong> (${escapeHtml(l.company)} · ${escapeHtml(l.service)}) — <em>${escapeHtml(l.status)}</em> · ${escapeHtml(l.age_days)} days old · $${escapeHtml(l.budget.toLocaleString())} · <a href="${escapeHtml(l.crm_link)}">Open in CRM</a></li>`
).join('');

const emailHtml = `
  <h2>AgencyDesk Morning Stale Leads Digest</h2>
  <p>Found <strong>${escapeHtml(staleLeads.length)}</strong> open lead(s) with no update in the last ${escapeHtml(staleDays)}+ days:</p>
  <ul>${htmlRows}</ul>
  <p><a href="${escapeHtml(safeBaseCrmUrl)}">Open AgencyDesk Leads Pipeline</a></p>
`;

return [{
  json: {
    stale_count: staleLeads.length,
    stale_days: staleDays,
    owner_whatsapp: ctx.owner_whatsapp,
    owner_email: ctx.owner_email,
    triggered_by: ctx.triggered_by,
    whatsapp_message: whatsappLines,
    email_subject: `AgencyDesk Morning Digest: ${staleLeads.length} stale open lead(s)`,
    email_html: emailHtml,
    checked_at: new Date().toISOString()
  }
}];

